const express = require('express');
const { Pool } = require('pg');

const pool = new Pool();
const router = express.Router();

router.get('/orders', async (req, res, next) => {
  try {
    const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);

    let cursor = null;
    if (req.query.cursor) {
      try {
        cursor = JSON.parse(Buffer.from(req.query.cursor, 'base64url').toString());
        if (!Array.isArray(cursor) || cursor.length !== 2) throw new Error();
      } catch {
        return res.status(400).json({ error: 'Invalid cursor' });
      }
    }

    // created_at is also selected as text because a JS Date drops microseconds,
    // which would make the cursor skip or repeat rows.
    // One extra row is fetched to tell whether another page exists.
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_ts
         FROM orders
         ${cursor ? 'WHERE (created_at, id) < ($2, $3)' : ''}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      cursor ? [limit + 1, ...cursor] : [limit + 1]
    );

    const page = rows.slice(0, limit);
    const last = page[page.length - 1];
    const nextCursor =
      rows.length > limit
        ? Buffer.from(JSON.stringify([last.cursor_ts, last.id])).toString('base64url')
        : null;

    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: nextCursor,
    });
  } catch (err) {
    next(err);
  }
});

module.exports = router;
